66	// Gateway is an HTTP reverse-proxy that routes OpenAI-compatible requests to llama-server processes.
67	type Gateway struct {
68		cfg        atomic.Pointer[config.Config]
69		mgr        processManager
70		log        *slog.Logger
71		affinity   *affinityTable
72		hub        nctxProvider
73		remote     *monitor.RemoteTracker
74		discovery  *monitor.ModelDiscovery
75		server     *http.Server
76		hfCacheDir string  // HuggingFace hub cache directory; empty disables scanning
77		hfCache    hfCache // cached HF model IDs
78	}
79	
80	// New creates a Gateway backed by the given process manager.
81	// hub may be nil; when non-nil, /monitor and /monitor/ws routes are registered.
82	// remote may be nil; when non-nil, remote provider requests are tracked.
83	func New(cfg *config.Config, mgr *process.Manager, hub *monitor.Hub, remote *monitor.RemoteTracker, discovery *monitor.ModelDiscovery, log *slog.Logger) *Gateway {
84		g := newGateway(cfg, mgr, hub, remote, discovery, log)
85		if home, err := os.UserHomeDir(); err == nil {
86			g.hfCacheDir = filepath.Join(home, ".cache", "huggingface", "hub")
87		}
88		return g
89	}
90	
91	func newGateway(cfg *config.Config, mgr processManager, hub *monitor.Hub, remote *monitor.RemoteTracker, discovery *monitor.ModelDiscovery, log *slog.Logger) *Gateway {
92		// Build affinity table from warmup models.
93		modelSlots := make(map[string]int, len(cfg.Warmup))
94		for _, name := range cfg.Warmup {
95			if params, ok := cfg.MatchModel(name); ok {
96				modelSlots[name] = params.Slots
97			}
98		}
99	
100		g := &Gateway{mgr: mgr, log: log, affinity: newAffinityTable(modelSlots), remote: remote, discovery: discovery}
101		g.cfg.Store(cfg)
102		// Store hub as nctxProvider nil-safely: a nil *monitor.Hub must not become
103		// a non-nil interface value, which would cause g.hub == nil checks to fail.
104		if hub != nil {
105			g.hub = hub
106		}
107	
108		mux := http.NewServeMux()
109		mux.HandleFunc("POST /v1/chat/completions", g.handleRoute)
110		mux.HandleFunc("POST /v1/completions", g.handleRoute)
111		mux.HandleFunc("POST /v1/embeddings", g.handleRoute)
112		mux.HandleFunc("POST /v1/rerank", g.handleRoute)
113		mux.HandleFunc("GET /v1/models", g.handleModels)
114		mux.HandleFunc("GET /health", g.handleHealth)
115	
116		if hub != nil {
117			mux.HandleFunc("GET /monitor", monitor.HandlePage)
118			mux.HandleFunc("GET /monitor/ws", monitor.HandleWS(hub))
119		}
120	
121		g.server = &http.Server{Addr: cfg.Listen, Handler: mux}
122		return g
123	}
