375	// handleRemote proxies a request to a remote OpenAI-compatible provider,
376	// bypassing the process manager entirely. body may be rewound if upstream_model rewrite is needed.
377	func (g *Gateway) handleRemote(w http.ResponseWriter, r *http.Request, modelName string, params config.ModelParams, cfg *config.Config, body []byte) {
378		provider, ok := cfg.Providers[params.Provider]
379		if !ok {
380			writeError(w, http.StatusInternalServerError, "server_error", "unknown provider: "+params.Provider, "config_error")
381			return
382		}
383	
384		if params.UpstreamModel != "" {
385			var obj map[string]json.RawMessage
386			if err := json.Unmarshal(body, &obj); err == nil {
387				if raw, err := json.Marshal(params.UpstreamModel); err == nil {
388					obj["model"] = raw
389					if rewritten, err := json.Marshal(obj); err == nil {
390						body = rewritten
391					}
392				}
393			}
394		}
395		r.Body = io.NopCloser(bytes.NewReader(body))
396		r.ContentLength = int64(len(body))
397	
398		baseTarget, err := url.Parse(provider.BaseURL)
399		if err != nil {
400			writeError(w, http.StatusInternalServerError, "server_error", "invalid provider URL", "config_error")
401			return
402		}
403	
404		apiKey := provider.APIKey
405		reqPath := r.URL.Path
406		upstreamModel := params.UpstreamModel
407		if upstreamModel == "" {
408			upstreamModel = modelName
409		}
410	
411		// Track remote request metrics.
412		var done func(int64, int)
413		if g.remote != nil {
414			done = g.remote.Start(modelName, params.Provider)
415		}
416		start := time.Now()
417	
418		proxy := &httputil.ReverseProxy{
419			Rewrite: func(pr *httputil.ProxyRequest) {
420				pr.SetURL(baseTarget)
421				pr.Out.URL.Path = baseTarget.Path + reqPath
422				pr.Out.Host = baseTarget.Host
423				pr.Out.Header.Set("Authorization", "Bearer "+apiKey)
424			},
425			FlushInterval: -1,
426			ModifyResponse: func(resp *http.Response) error {
427				resp.Header.Set("X-Wire-Model", upstreamModel)
428				if done != nil {
429					done(time.Since(start).Nanoseconds(), resp.StatusCode)
430					done = nil // prevent double-call
431				}
432				return rewriteContextLengthError(resp)
433			},
434			ErrorHandler: func(w http.ResponseWriter, _ *http.Request, err error) {
435				g.log.Error("remote proxy error", "model", modelName, "provider", params.Provider, "error", err)
436				if done != nil {
437					done(time.Since(start).Nanoseconds(), 502)
438					done = nil
439				}
440				writeError(w, http.StatusBadGateway, "server_error", "upstream error: "+err.Error(), "upstream_error")
441			},
442		}
443	
444		proxy.ServeHTTP(w, r)
445	}
