447	// estimateTokens approximates the token count of a request body using a
448	// chars/4 heuristic. It extracts text from messages[].content (chat) and the
449	// input field (embeddings). Returns 0 on parse failure or empty content.
450	func estimateTokens(body []byte) int {
451		var req struct {
452			Messages []struct {
453				Content json.RawMessage `json:"content"`
454			} `json:"messages"`
455			Input json.RawMessage `json:"input"`
456		}
457		if err := json.Unmarshal(body, &req); err != nil {
458			return 0
459		}
460	
461		total := 0
462		for _, msg := range req.Messages {
463			if len(msg.Content) == 0 {
464				continue
465			}
466			var s string
467			if err := json.Unmarshal(msg.Content, &s); err == nil {
468				total += len(s)
469				continue
470			}
471			var parts []struct {
472				Text string `json:"text"`
473			}
474			if err := json.Unmarshal(msg.Content, &parts); err == nil {
475				for _, p := range parts {
476					total += len(p.Text)
477				}
478			}
479		}
480	
481		if len(req.Input) > 0 {
482			var s string
483			if err := json.Unmarshal(req.Input, &s); err == nil {
484				total += len(s)
485			} else {
486				var arr []string
487				if err := json.Unmarshal(req.Input, &arr); err == nil {
488					for _, s := range arr {
489						total += len(s)
490					}
491				}
492			}
493		}
494	
495		return total / 4
496	}
