8		"fmt"
9		"io"
10		"log/slog"
11		"net/http"
12		"net/http/httputil"
13		"net/url"
14		"os"
15		"path/filepath"
16		"slices"
17		"strings"
18		"sync"
19		"sync/atomic"
20		"time"
21	
22		"github.com/nogo/wire/internal/config"
23		"github.com/nogo/wire/internal/monitor"
24		"github.com/nogo/wire/internal/process"
25	)
26	
27	// nctxProvider wraps the NCtx lookup; *monitor.Hub satisfies this interface.
28	type nctxProvider interface {
29		NCtx(model string) int
30	}
31	
32	// processManager is the subset of process.Manager the Gateway depends on.
33	type processManager interface {
34		Loaded(name string) bool
35		// LoadOrGet returns a ticket for the named model, loading it on demand if
36		// not already running. The caller waits on ticket.Ready() for the backend
37		// address and must call ticket.Release() when the request completes.
38		LoadOrGet(modelName string, params config.ModelParams) *process.LoadTicket
39		// ListModels returns all known models in non-idle states.
40		ListModels() []monitor.ModelInfo
41	}
42	
43	// hfCache caches HF model IDs with a TTL to avoid repeated filesystem I/O.
44	type hfCache struct {
45		mu    sync.Mutex
46		ids   []string
47		until time.Time
48	}
49	
50	func (c *hfCache) get(ttl time.Duration) ([]string, bool) {
51		c.mu.Lock()
52		defer c.mu.Unlock()
53		if time.Now().Before(c.until) {
54			return c.ids, true
55		}
56		return nil, false
57	}
58	
59	func (c *hfCache) set(ids []string, ttl time.Duration) {
60		c.mu.Lock()
61		defer c.mu.Unlock()
62		c.ids = ids
63		c.until = time.Now().Add(ttl)
64	}
65	
66	// Gateway is an HTTP reverse-proxy that routes OpenAI-compatible requests to llama-server processes.
67	type Gateway struct {
68		cfg        atomic.Pointer[config.Config]
69		mgr        processManager
70		log        *slog.Logger
71		affinity   *affinityTable
72		hub        nctxProvider
73		remote     *monitor.RemoteTracker
74		discovery  *monitor.ModelDiscovery
75		server     *http.Server
76		hfCacheDir string  // HuggingFace hub cache directory; empty disables scanning
77		hfCache    hfCache // cached HF model IDs
78	}
79	
80	// New creates a Gateway backed by the given process manager.
81	// hub may be nil; when non-nil, /monitor and /monitor/ws routes are registered.
82	// remote may be nil; when non-nil, remote provider requests are tracked.
83	func New(cfg *config.Config, mgr *process.Manager, hub *monitor.Hub, remote *monitor.RemoteTracker, discovery *monitor.ModelDiscovery, log *slog.Logger) *Gateway {
84		g := newGateway(cfg, mgr, hub, remote, discovery, log)
85		if home, err := os.UserHomeDir(); err == nil {
86			g.hfCacheDir = filepath.Join(home, ".cache", "huggingface", "hub")
87		}
88		return g
89	}
90	
91	func newGateway(cfg *config.Config, mgr processManager, hub *monitor.Hub, remote *monitor.RemoteTracker, discovery *monitor.ModelDiscovery, log *slog.Logger) *Gateway {
92		// Build affinity table from warmup models.
93		modelSlots := make(map[string]int, len(cfg.Warmup))
94		for _, name := range cfg.Warmup {
95			if params, ok := cfg.MatchModel(name); ok {
96				modelSlots[name] = params.Slots
97			}
98		}
99	
100		g := &Gateway{mgr: mgr, log: log, affinity: newAffinityTable(modelSlots), remote: remote, discovery: discovery}
101		g.cfg.Store(cfg)
102		// Store hub as nctxProvider nil-safely: a nil *monitor.Hub must not become
103		// a non-nil interface value, which would cause g.hub == nil checks to fail.
104		if hub != nil {
105			g.hub = hub
106		}
107	
108		mux := http.NewServeMux()
109		mux.HandleFunc("POST /v1/chat/completions", g.handleRoute)
110		mux.HandleFunc("POST /v1/completions", g.handleRoute)
111		mux.HandleFunc("POST /v1/embeddings", g.handleRoute)
112		mux.HandleFunc("POST /v1/rerank", g.handleRoute)
113		mux.HandleFunc("GET /v1/models", g.handleModels)
114		mux.HandleFunc("GET /health", g.handleHealth)
115	
116		if hub != nil {
117			mux.HandleFunc("GET /monitor", monitor.HandlePage)
118			mux.HandleFunc("GET /monitor/ws", monitor.HandleWS(hub))
119		}
120	
121		g.server = &http.Server{Addr: cfg.Listen, Handler: mux}
122		return g
123	}
124	
125	// ListenAndServe starts the HTTP server and shuts it down when ctx is cancelled.
126	func (g *Gateway) ListenAndServe(ctx context.Context) error {
127		errCh := make(chan error, 1)
128		go func() {
129			if err := g.server.ListenAndServe(); err != nil && err != http.ErrServerClosed {
130				errCh <- err
131			}
132		}()
133		select {
134		case err := <-errCh:
135			return err
136		case <-ctx.Done():
137			shutCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
138			defer cancel()
139			return g.server.Shutdown(shutCtx)
140		}
141	}
142	
143	// UpdateConfig atomically replaces the gateway's config. New requests will use
144	// the updated model patterns and params immediately.
145	func (g *Gateway) UpdateConfig(cfg *config.Config) {
146		g.cfg.Store(cfg)
147	}
148	
149	// handleRoute extracts the model field from the JSON body and proxies to the matching process.
150	// If the model is known but not loaded, it is started on demand; the HTTP connection
151	// is held open until the model becomes healthy.
152	func (g *Gateway) handleRoute(w http.ResponseWriter, r *http.Request) {
153		// Read body once for all operations: model extraction, token estimation, slot affinity.
154		allBody, err := io.ReadAll(r.Body)
155		if err != nil {
156			writeError(w, http.StatusBadRequest, "invalid_request_error", "failed to read body", "bad_request")
157			return
158		}
159	
160		var payload struct {
161			Model string `json:"model"`
162		}
163		if err := json.Unmarshal(allBody, &payload); err != nil {
164			writeError(w, http.StatusBadRequest, "invalid_request_error", "invalid JSON: "+err.Error(), "bad_request")
165			return
166		}
167		if payload.Model == "" {
168			writeError(w, http.StatusBadRequest, "invalid_request_error", "missing model field", "bad_request")
169			return
170		}
171	
172		currentCfg := g.cfg.Load()
173		params, ok := currentCfg.MatchModel(payload.Model)
174		var snap monitor.DiscoverySnapshot
175		if !ok && g.discovery != nil {
176			snap = g.discovery.Snapshot()
177			if dm, found := snap.Lookup(payload.Model); found {
178				if _, provOk := currentCfg.Providers[dm.Provider]; provOk {
179					params = config.ModelParams{Provider: dm.Provider}
180					ok = true
181				}
182			}
183		}
184		if !ok {
185			writeError(w, http.StatusNotFound, "invalid_request_error", "unknown model: "+payload.Model, "model_not_found")
186			return
187		}
188	
189		if params.IsRemote() {
190			g.handleRemote(w, r, payload.Model, params, currentCfg, allBody)
191			return // handleRemote handles body rewrite if needed
192		}
193	
194		ticket := g.mgr.LoadOrGet(payload.Model, params)
195		var addr string
196		select {
197		case a, ok := <-ticket.Ready():
198			if !ok {
199				err := ticket.Err()
200				if errors.Is(err, context.DeadlineExceeded) {
201					writeError(w, http.StatusGatewayTimeout, "server_error", "model load timed out: "+err.Error(), "load_timeout")
202					return
203				}
204				writeError(w, http.StatusServiceUnavailable, "server_error", err.Error(), "model_not_loaded")
205				return
206			}
207			addr = a
208		case <-r.Context().Done():
209			writeError(w, http.StatusServiceUnavailable, "server_error", "request cancelled", "request_cancelled")
210			return
211		}
212		defer ticket.Release()
213	
214		if g.hub != nil {
215			if nCtx := g.hub.NCtx(payload.Model); nCtx > 0 {
216				if est := estimateTokens(allBody); est > 0 && est > nCtx*9/10 {
217					writeError(w, http.StatusBadRequest, "invalid_request_error",
218						fmt.Sprintf("estimated %d tokens exceeds context window of %d (n_ctx)", est, nCtx),
219						"context_length_exceeded")
220					return
221				}
222			}
223		}
224	
225		g.affinity.Register(payload.Model, params.Slots)
226	
227		hash := prefixHash(allBody)
228		if slotID, assigned := g.affinity.Assign(payload.Model, hash); assigned {
229			allBody = injectSlot(allBody, slotID)
230		}
231		r.Body = io.NopCloser(bytes.NewReader(allBody))
232		r.ContentLength = int64(len(allBody))
233	
234		target, parseErr := url.Parse(addr)
235		if parseErr != nil {
236			writeError(w, http.StatusInternalServerError, "server_error", "invalid backend URL", "internal_error")
237			return
238		}
239	
240		proxy := &httputil.ReverseProxy{
241			Rewrite: func(pr *httputil.ProxyRequest) {
242				pr.SetURL(target)
243				pr.Out.Host = target.Host
244			},
245			FlushInterval:  -1,
246			ModifyResponse: rewriteContextLengthError,
247			ErrorHandler: func(w http.ResponseWriter, _ *http.Request, err error) {
248				g.log.Error("proxy error", "model", payload.Model, "error", err)
249				writeError(w, http.StatusBadGateway, "server_error", "upstream error: "+err.Error(), "upstream_error")
250			},
251		}
252	
253		proxy.ServeHTTP(w, r)
254	}
255	
256	// handleModels returns all known models with their current status.
257	func (g *Gateway) handleModels(w http.ResponseWriter, _ *http.Request) {
258		type modelObj struct {
259			ID           string   `json:"id"`
260			Object       string   `json:"object"`
261			Type         string   `json:"type"`
262			Status       string   `json:"status,omitempty"`
263			Capabilities []string `json:"capabilities,omitempty"`
264			Provider     string   `json:"provider,omitempty"`
265		}
266		type modelsResp struct {
267			Object string     `json:"object"`
268			Data   []modelObj `json:"data"`
269		}
270	
271		models := g.Models()
272		data := make([]modelObj, 0, len(models))
273		for _, m := range models {
274			data = append(data, modelObj{
275				ID:           m.ID,
276				Object:       m.Object,
277				Type:         m.Type,
278				Status:       m.Status,
279				Capabilities: m.Capabilities,
280				Provider:     m.Provider,
281			})
282		}
283	
284		w.Header().Set("Content-Type", "application/json")
285		json.NewEncoder(w).Encode(modelsResp{Object: "list", Data: data}) //nolint:errcheck
286	}
287	
288	// Models returns all known models as ModelInfo slice.
289	func (g *Gateway) Models() []monitor.ModelInfo {
290		cfg := g.cfg.Load()
291		var models []monitor.ModelInfo
292	
293		// Local models from Manager (loaded/running)
294		localModels := g.mgr.ListModels()
295		for _, mi := range localModels {
296			obj := monitor.ModelInfo{
297				ID:     mi.ID,
298				Object: "model",
299				Type:   "local",
300				Status: mi.Status,
301			}
302			if p, ok := cfg.MatchModel(mi.ID); ok {
303				obj.Capabilities = p.Capabilities
304			}
305			models = append(models, obj)
306		}
307	
308		listed := make(map[string]bool, len(models))
309		for _, m := range models {
310			listed[m.ID] = true
311		}
312	
313		// HF cache models (local but not loaded)
314		for _, cm := range g.scanHFCache() {
315			if listed[cm] {
316				continue
317			}
318			models = append(models, monitor.ModelInfo{
319				ID:     cm,
320				Object: "model",
321				Type:   "local",
322				Status: "available",
323			})
324			listed[cm] = true
325		}
326	
327		// Configured remote models
328		configuredRemote := make(map[string]bool)
329		for pattern, p := range cfg.Models {
330			if !p.IsRemote() {
331				continue
332			}
333			configuredRemote[pattern] = true
334			models = append(models, monitor.ModelInfo{
335				ID:           pattern,
336				Object:       "model",
337				Type:         "remote",
338				Status:       "available",
339				Capabilities: p.Capabilities,
340				Provider:     p.Provider,
341			})
342		}
343	
344		// Discovered remote models
345		if g.discovery != nil {
346			for _, dm := range g.discovery.Snapshot().AllModels() {
347				if configuredRemote[dm.ID] {
348					continue
349				}
350				models = append(models, monitor.ModelInfo{
351					ID:       dm.ID,
352					Object:   "model",
353					Type:     "remote",
354					Status:   "available",
355					Provider: dm.Provider,
356				})
357			}
358		}
359	
360		return models
361	}
362	
363	// handleHealth returns 200 if at least one warmup model is healthy, 503 otherwise.
364	func (g *Gateway) handleHealth(w http.ResponseWriter, _ *http.Request) {
365		w.Header().Set("Content-Type", "application/json")
366		if slices.ContainsFunc(g.cfg.Load().Warmup, g.mgr.Loaded) {
367			w.WriteHeader(http.StatusOK)
368			json.NewEncoder(w).Encode(map[string]string{"status": "ok"}) //nolint:errcheck
369			return
370		}
371		w.WriteHeader(http.StatusServiceUnavailable)
372		json.NewEncoder(w).Encode(map[string]string{"status": "degraded"}) //nolint:errcheck
373	}
374	
375	// handleRemote proxies a request to a remote OpenAI-compatible provider,
376	// bypassing the process manager entirely. body may be rewound if upstream_model rewrite is needed.
377	func (g *Gateway) handleRemote(w http.ResponseWriter, r *http.Request, modelName string, params config.ModelParams, cfg *config.Config, body []byte) {
378		provider, ok := cfg.Providers[params.Provider]
379		if !ok {
380			writeError(w, http.StatusInternalServerError, "server_error", "unknown provider: "+params.Provider, "config_error")
381			return
382		}
383	
384		if params.UpstreamModel != "" {
385			var obj map[string]json.RawMessage
386			if err := json.Unmarshal(body, &obj); err == nil {
387				if raw, err := json.Marshal(params.UpstreamModel); err == nil {
388					obj["model"] = raw
389					if rewritten, err := json.Marshal(obj); err == nil {
390						body = rewritten
391					}
392				}
393			}
394		}
395		r.Body = io.NopCloser(bytes.NewReader(body))
396		r.ContentLength = int64(len(body))
397	
398		baseTarget, err := url.Parse(provider.BaseURL)
399		if err != nil {
400			writeError(w, http.StatusInternalServerError, "server_error", "invalid provider URL", "config_error")
401			return
402		}
403	
404		apiKey := provider.APIKey
405		reqPath := r.URL.Path
406		upstreamModel := params.UpstreamModel
407		if upstreamModel == "" {
408			upstreamModel = modelName
409		}
410	
411		// Track remote request metrics.
412		var done func(int64, int)
413		if g.remote != nil {
414			done = g.remote.Start(modelName, params.Provider)
415		}
416		start := time.Now()
417	
418		proxy := &httputil.ReverseProxy{
419			Rewrite: func(pr *httputil.ProxyRequest) {
420				pr.SetURL(baseTarget)
421				pr.Out.URL.Path = baseTarget.Path + reqPath
422				pr.Out.Host = baseTarget.Host
423				pr.Out.Header.Set("Authorization", "Bearer "+apiKey)
424			},
425			FlushInterval: -1,
426			ModifyResponse: func(resp *http.Response) error {
427				resp.Header.Set("X-Wire-Model", upstreamModel)
428				if done != nil {
429					done(time.Since(start).Nanoseconds(), resp.StatusCode)
430					done = nil // prevent double-call
431				}
432				return rewriteContextLengthError(resp)
433			},
434			ErrorHandler: func(w http.ResponseWriter, _ *http.Request, err error) {
435				g.log.Error("remote proxy error", "model", modelName, "provider", params.Provider, "error", err)
436				if done != nil {
437					done(time.Since(start).Nanoseconds(), 502)
438					done = nil
439				}
440				writeError(w, http.StatusBadGateway, "server_error", "upstream error: "+err.Error(), "upstream_error")
441			},
442		}
443	
444		proxy.ServeHTTP(w, r)
445	}
446	
447	// estimateTokens approximates the token count of a request body using a
448	// chars/4 heuristic. It extracts text from messages[].content (chat) and the
449	// input field (embeddings). Returns 0 on parse failure or empty content.
450	func estimateTokens(body []byte) int {
451		var req struct {
452			Messages []struct {
453				Content json.RawMessage `json:"content"`
454			} `json:"messages"`
455			Input json.RawMessage `json:"input"`
456		}
457		if err := json.Unmarshal(body, &req); err != nil {
458			return 0
459		}
460	
461		total := 0
462		for _, msg := range req.Messages {
463			if len(msg.Content) == 0 {
464				continue
465			}
466			var s string
467			if err := json.Unmarshal(msg.Content, &s); err == nil {
468				total += len(s)
469				continue
470			}
471			var parts []struct {
472				Text string `json:"text"`
473			}
474			if err := json.Unmarshal(msg.Content, &parts); err == nil {
475				for _, p := range parts {
476					total += len(p.Text)
477				}
478			}
479		}
480	
481		if len(req.Input) > 0 {
482			var s string
483			if err := json.Unmarshal(req.Input, &s); err == nil {
484				total += len(s)
485			} else {
486				var arr []string
487				if err := json.Unmarshal(req.Input, &arr); err == nil {
488					for _, s := range arr {
489						total += len(s)
490					}
491				}
492			}
493		}
494	
495		return total / 4
496	}
497	
498	// rewriteContextLengthError inspects non-2xx upstream responses for a
499	// context_length_exceeded error code and rewrites the status to 400 to match
500	// the OpenAI API standard. llama-server returns these as 500.
501	func rewriteContextLengthError(resp *http.Response) error {
502		if resp.StatusCode >= 200 && resp.StatusCode < 300 {
503			return nil
504		}
505	
506		body, err := io.ReadAll(resp.Body)
507		resp.Body.Close()
508		if err != nil {
509			resp.Body = io.NopCloser(bytes.NewReader(nil))
510			return nil
511		}
512	
513		var envelope struct {
514			Error struct {
515				Code string `json:"code"`
516			} `json:"error"`
517		}
518		if json.Unmarshal(body, &envelope) == nil && envelope.Error.Code == "context_length_exceeded" {
519			resp.StatusCode = http.StatusBadRequest
520			resp.Status = http.StatusText(http.StatusBadRequest)
521		}
522	
523		resp.Body = io.NopCloser(bytes.NewReader(body))
524		return nil
525	}
526	
527	const hfCacheTTL = 30 * time.Second
528	
529	// scanHFCache returns cached model IDs (org/repo:QUANT) for all GGUF files
530	// found in the HuggingFace hub cache. Results are cached for 30s to avoid
531	// repeated filesystem I/O on /v1/models calls.
532	func (g *Gateway) scanHFCache() []string {
533		if g.hfCacheDir == "" {
534			return nil
535		}
536		if ids, ok := g.hfCache.get(hfCacheTTL); ok {
537			return ids
538		}
539	
540		entries, err := os.ReadDir(g.hfCacheDir)
541		if err != nil {
542			return nil
543		}
544	
545		var models []string
546		for _, entry := range entries {
547			name := entry.Name()
548			if !entry.IsDir() || !strings.HasPrefix(name, "models--") {
549				continue
550			}
551			// models--org--repo → org/repo
552			parts := strings.SplitN(name, "--", 3)
553			if len(parts) != 3 {
554				continue
555			}
556			repo := parts[1] + "/" + parts[2]
557	
558			// Walk snapshots for .gguf files.
559			snapshotsDir := filepath.Join(g.hfCacheDir, name, "snapshots")
560			snapshots, err := os.ReadDir(snapshotsDir)
561			if err != nil {
562				continue
563			}
564			seen := make(map[string]bool)
565			for _, snap := range snapshots {
566				if !snap.IsDir() {
567					continue
568				}
569				ggufs, err := filepath.Glob(filepath.Join(snapshotsDir, snap.Name(), "*.gguf"))
570				if err != nil {
571					continue
572				}
573				for _, path := range ggufs {
574					base := strings.TrimSuffix(filepath.Base(path), ".gguf")
575					// Skip auxiliary files (e.g. mmproj-BF16.gguf).
576					if strings.HasPrefix(base, "mmproj") {
577						continue
578					}
579					// Extract quant: look for Q prefix after the last dash-or-dot, but handle
580					// compound quants like Q5_K_M. The pattern is: model-name[-size]Q<num>[_<variant>]
581					// e.g. "Qwen3-4B-Q8_0" → "Q8_0", "Qwen3-4B-Q5_K_M" → "Q5_K_M"
582					quant := extractQuant(base)
583					if quant == "" {
584						continue
585					}
586					id := repo + ":" + quant
587					if !seen[id] {
588						seen[id] = true
589						models = append(models, id)
590					}
591				}
592			}
593		}
594		g.hfCache.set(models, hfCacheTTL)
595		return models
596	}
597	
598	// extractQuant extracts the quantization suffix from a GGUF filename.
599	// Handles patterns like "Qwen3-4B-Q8_0", "Qwen3-4B-Q5_K_M", "Phi-4-mini-instruct.Q8_0".
600	// Returns empty string if no valid quant is found.
601	func extractQuant(base string) string {
602		// Find last Q<num> and stop at -XB boundary (e.g., -4B, -8B)
603		for i := len(base) - 1; i >= 0; i-- {
604			if i > 0 && base[i] == 'B' && base[i-1] >= '0' && base[i-1] <= '9' {
605				break
606			}
607			if i+1 < len(base) && base[i] == 'Q' && base[i+1] >= '0' && base[i+1] <= '9' {
608				return base[i:]
609			}
610		}
611		return ""
612	}
613	
614	// writeError writes an OpenAI-format JSON error response.
615	func writeError(w http.ResponseWriter, status int, errType, message, code string) {
616		w.Header().Set("Content-Type", "application/json")
617		w.WriteHeader(status)
618		json.NewEncoder(w).Encode(map[string]any{ //nolint:errcheck
619			"error": map[string]any{
620				"message": message,
621				"type":    errType,
622				"code":    code,
623			},
624		})
625	}
